#include "rpg/pve.hpp"
#include <iostream>
using namespace rpg;
void check(bool x,const char* m){if(!x){throw std::runtime_error(m);}}
PveDefinition config(){PveDefinition d;d.id="phases";d.attempt_id="phase";d.boss_id="B";d.roster={{"A",Team::A,1000,700,100},{"B",Team::B,1000,10,90}};for(auto& f:d.roster){f.stats.block=0;}d.rules.combat_model=resolution::CombatModel::FunnelV1;d.rules.timing=TimingProfile::ActionBar;return d;}
int main(){try{
 auto d=config();PhaseMutation p1,p2;p1.kit={{"p1","B",3,TargetRule::Enemy,{{EffectKind::Damage}}}};p2.kit={{"p2","B",4,TargetRule::Enemy,{{EffectKind::Damage}}}};p2.kit[0].effects[0].power_ratio=20000;d.phases={{"70",PvePhaseTrigger::HealthThreshold,7000,p1},{"35",PvePhaseTrigger::HealthThreshold,3500,p2}};
 ScoreLedger ledger;PveEncounter phased(d,ledger);auto r=phased.apply({"A",ActionType::Attack,"B"});check(r.action.accepted()&&r.phase_events.size()==2&&r.phase_events[0].id=="70"&&r.phase_events[1].id=="35"&&phased.battle().find("B")->health==300,"two thresholds preserve mandatory events");check(phased.battle().accepted_actions()==1&&phased.battle().snapshot().next_action_id==2,"phase creates no action/turn");r=phased.apply({"B",ActionType::Skill,"A","p2"});check(r.action.accepted()&&phased.battle().find("A")->health==980,"advanced kit active");
 auto reserve=config();reserve.attempt_id="reserve";Definition summon{"S",Team::B,100,5,150};summon.role=EntityRole::Summon;summon.summoner_id="B";reserve.roster.push_back(summon);reserve.reserve_summons={"S"};PhaseMutation spawn;spawn.activate_summons={"S"};reserve.phases={{"spawn",PvePhaseTrigger::HealthThreshold,7000,spawn}};PveEncounter summoned(reserve,ledger);check(summoned.battle().find("S")->health==0,"reserve inactive");r=summoned.apply({"A",ActionType::Attack,"B"});check(r.phase_events.size()==1&&summoned.battle().find("S")->health==100&&summoned.battle().find("S")->ap==0,"explicit phase summon");auto copy=summoned.battle();const auto before=copy.snapshot();PhaseMutation invalid;invalid.kit={{"bad","A",0,TargetRule::Enemy,{{EffectKind::Damage}}}};bool rejected=false;try{static_cast<void>(copy.transition_phase("B",invalid));}catch(const std::invalid_argument&){rejected=true;}check(rejected&&copy.snapshot()==before,"invalid phase atomic");
 auto stable=config();stable.attempt_id="stable";stable.phases={{"unchanged",PvePhaseTrigger::HealthThreshold,7000,{}}};PveEncounter unchanged(stable,ledger);auto kits=unchanged.battle().snapshot().rules.skills;r=unchanged.apply({"A",ActionType::Attack,"B"});check(r.phase_events.size()==1&&unchanged.battle().snapshot().rules.skills==kits,"phase may preserve kit");
 auto cycle=config();cycle.attempt_id="cycle";cycle.roster[0].attack=1;cycle.roster[1].max_health=100000;cycle.turn_cycle=PveTurnCycle{1,{{"offense",{}},{"defense",{}}}};PveEncounter alternating(cycle,ledger);std::vector<std::string> names;for(int i=0;i<9&&names.size()<3;++i){auto a=choose_basic_attack(alternating.battle());check(a.has_value(),"cycle action");auto step=alternating.apply(*a);for(const auto& event:step.phase_events){names.push_back(event.id);}}check(names.size()==3&&names[0]=="offense"&&names[1]=="defense"&&names[2]=="offense","repeating boss turn cycle");
 auto mapped=config();mapped.attempt_id="mapped";mapped.roster[0].speed=90;mapped.roster[1].speed=200;mapped.rules.skills={{"old","B",4,TargetRule::Enemy,{{EffectKind::Damage}}}};PveEncounter initial(mapped,ledger);check(initial.apply({"B",ActionType::Skill,"A","old"}).action.accepted(),"old cooldown");auto exact=initial.battle();const auto previous=exact.snapshot();PhaseMutation remap;remap.kit={{"new","B",5,TargetRule::Enemy,{{EffectKind::Damage}}}};remap.cooldowns=PhaseCooldowns::MapExplicit;remap.mappings={{"old","new"}};static_cast<void>(exact.transition_phase("B",remap));check(exact.find("B")->cooldowns[0].remaining==3&&exact.snapshot().logical_time==previous.logical_time&&exact.accepted_actions()==previous.accepted_actions,"map cooldown without resetting AP clock");
 Definition owner{"O",Team::A,10,1,50},ally{"P",Team::A,1000,1,40},s{"S",Team::A,100,1,30},enemy{"B",Team::B,1000,100,200};s.role=EntityRole::Summon;s.summoner_id="O";owner.stats.block=0;ally.stats.block=0;s.stats.block=0;enemy.stats.block=0;BattleRules life;life.combat_model=resolution::CombatModel::FunnelV1;life.skills={{"blast","B",0,TargetRule::EnemyTeam,{{EffectKind::Damage}}}};InitialRuntime reviveOwner{"O",50,{{EffectKind::AutoRevive,2,TickPolicy::NaturalOnly,0,10}}, {}};Battle dismissed({owner,ally,s,enemy},life,{}, {reviveOwner});check(dismissed.apply({"B",ActionType::Skill,"O","blast"}).accepted()&&dismissed.find("O")->health==10&&dismissed.find("S")->health==0&&dismissed.find("S")->summon_dismissed,"summoner revive does not restore dissipated summon");
 Battle initialOrphan({owner,ally,s,enemy},life,{{"O",0},{"P",1000},{"S",100},{"B",1000}});check(initialOrphan.find("S")->health==0,"initial orphan summon absent");
 std::vector<SquadDefinition> teams;for(int i=1;i<=3;++i){BattleRules local;local.combat_model=resolution::CombatModel::FunnelV1;local.action_budget=ActionBudget{1,LimitOutcome::DefeatA};Definition member{"U"+std::to_string(i),Team::A,100,1,100};member.stats.block=0;teams.push_back({"group"+std::to_string(i),{{member.id,member}},local});}Definition persistent{"K",Team::B,1000,1,50};persistent.stats.block=0;Status special{EffectKind::SilverShield,2,TickPolicy::NaturalOnly,0,150};special.border=StatusBorder::Silver;SequentialSquads specialCarry(SequentialDefinition{"special-seq",2,teams,persistent,BossRuntimeCarry::PreserveSpecialBordersV2,std::nullopt,{}, {special}});auto swap=specialCarry.apply({"U1",ActionType::Attack,"K"});check(swap.squad_advanced&&has_status(*specialCarry.battle().find("K"),EffectKind::SilverShield),"explicit sequence v2 preserves special border");
 std::cout<<"REG_PHASE_TESTS_RESULT passed=10 total=10\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
